INSERT INTO public.questions (code, book, statement, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, reference, difficulty, active)
VALUES
(801, 'o_que_e_espiritismo', 'Segundo a biografia escrita por Henri Sausse em ''O Que é o Espiritismo'', em que cidade e data nasceu Allan Kardec?', 'Em Lyon, a 3 de outubro de 1804.', 'Em Paris, a 18 de abril de 1804.', 'Em Bordeaux, a 31 de março de 1805.', 'Em Tours, a 3 de novembro de 1803.', 'Em Genebra, a 15 de agosto de 1804.', 'A', 'Henri Sausse registra que Allan Kardec nasceu em Lyon a 3 de outubro de 1804, recebendo o nome civil de Hippolyte Léon Denizard Rivail.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'facil', true),
(802, 'o_que_e_espiritismo', 'Qual era o nome civil completo do Codificador do Espiritismo antes de adotar o pseudônimo Allan Kardec?', 'Jean-Baptiste Léon Fortier Rivail.', 'Hippolyte Léon Denizard Rivail.', 'Pierre-Paul Didier Baudin.', 'Camille Nicolas Denizard Flammarion.', 'Henri Léon Sausse Rivail.', 'B', 'Filho do magistrado Jean-Baptiste Antoine Rivail, o Codificador chamava-se no registro civil Hippolyte Léon Denizard Rivail.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'facil', true),
(803, 'o_que_e_espiritismo', 'Em qual instituição suíça o jovem Denizard Rivail realizou seus estudos pedagógicos sob a direção de um célebre educador?', 'Na Academia de Genebra, sob a direção de Jean-Jacques Rousseau.', 'No Colégio de Lausanne, dirigido pelo pastor Charles Wagner.', 'No Instituto de Yverdon, dirigido pelo célebre professor Pestalozzi.', 'No Liceu de Zurique, dirigido por Heinrich Lavater.', 'Na Escola Politécnica de Berna, sob orientação de Girard.', 'C', 'Seus pais enviaram-no para o famoso Instituto de Yverdon, na Suíça, dirigido por Johann Heinrich Pestalozzi, de quem se tornou discípulo e colaborador.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'facil', true),
(804, 'o_que_e_espiritismo', 'Com quem o professor Hippolyte Léon Denizard Rivail se casou em 6 de fevereiro de 1832?', 'Com Ermance Dufaux.', 'Com Caroline e Julie Baudin.', 'Com Ruth Japhet.', 'Com Amélie Gabrielle Boudet.', 'Com Madame Plainemaison.', 'D', 'Em 1832, o professor Rivail desposou Amélie Gabrielle Boudet, culta professora que foi sua dedicada companheira e colaboradora durante toda a vida.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'medio', true),
(805, 'o_que_e_espiritismo', 'Em que ano, segundo Henri Sausse, o professor Rivail ouviu falar pela primeira vez das mesas girantes por meio do magnetizador Sr. Fortier?', 'Em 1848, logo após os fenômenos de Hydesville.', 'Em 1850, durante um congresso de magnetismo em Lyon.', 'Em 1852, na Academia Real de Ciências de Arras.', 'Em 1857, pouco antes de publicar O Livro dos Espíritos.', 'Em 1854, quando o Sr. Fortier lhe relatou que as mesas não apenas giravam, mas também falavam.', 'E', 'Foi em 1854 que o Sr. Fortier, magnetizador de suas relações, falou-lhe pela primeira vez das mesas girantes e das comunicações obtidas por batidas.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'medio', true),
(806, 'o_que_e_espiritismo', 'Na casa de quem, em maio de 1855, o professor Rivail presenciou pela primeira vez o fenômeno das mesas que giravam, saltavam e corriam?', 'Na casa da Sra. Plainemaison, na rua Grange-Batelière.', 'Na residência de Camille Flammarion, no Observatório de Paris.', 'No salão literário do livreiro Didier, no Palais-Royal.', 'No gabinete médico do Dr. Paul Bert.', 'No Instituto Técnico da rua de Sèvres.', 'A', 'Em maio de 1855, acompanhado do Sr. Pottié, Rivail assistiu pela primeira vez às experiências de mesas girantes e escrita em ardósia na casa da Sra. Plainemaison.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'medio', true),
(807, 'o_que_e_espiritismo', 'Na casa de qual família o professor Rivail iniciou seus estudos regulares e metódicos das comunicações psicográficas por meio de duas jovens médiuns?', 'Na casa da família Fortier.', 'Na casa da família Baudin, com as jovens Caroline e Julie.', 'Na casa da família Sausse, em Lyon.', 'Na casa da família Delanne, em Paris.', 'Na casa da família Lachâtre, em Toulon.', 'B', 'Foi nas reuniões semanais na casa da família Baudin, onde escreviam na cesta-pião as jovens médiuns Srta. Julie e Srta. Caroline Baudin, que Rivail iniciou seus estudos sérios.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'medio', true),
(808, 'o_que_e_espiritismo', 'Por meio de qual médium sonâmbula o professor Rivail fez a verificação e revisão completa dos cinquenta cadernos que deram origem a ''O Livro dos Espíritos''?', 'Sra. Plainemaison.', 'Sra. Amélie Boudet.', 'Srta. Ruth Japhet.', 'Srta. Aline Carlotti.', 'Sra. d''Espérance.', 'C', 'Cerca de cinquenta cadernos confiados pelos Srs. Carlotti, René Taillandier, Tiedeman-Manthese e Sardou foram coordenados e revistos com o concurso da médium Srta. Japhet.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'dificil', true),
(809, 'o_que_e_espiritismo', 'Em que data veio a lume a primeira edição de ''O Livro dos Espíritos'', marco inaugural da Codificação Espírita?', '1 de janeiro de 1858.', '3 de outubro de 1856.', '31 de março de 1857.', '18 de abril de 1857.', '15 de agosto de 1859.', 'D', 'A primeira edição de O Livro dos Espíritos foi publicada em Paris, pela livraria Dentu, no Palais-Royal, em 18 de abril de 1857.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'facil', true),
(810, 'o_que_e_espiritismo', 'Por que o professor Rivail decidiu assinar as obras espíritas com o pseudônimo Allan Kardec?', 'Para ocultar sua nacionalidade francesa diante das autoridades eclesiásticas.', 'Porque seu editor exigiu um nome de sonoridade inglesa para ampliar as vendas.', 'Por imposição da Academia Real de Ciências de Arras.', 'Para homenagear seu antigo mestre suíço Pestalozzi.', 'Para não confundir sua obra espírita, fruto do ensino dos Espíritos, com seus conhecidos livros pedagógicos assinados com o nome civil.', 'E', 'Sendo seu nome civil muito conhecido pelas obras didáticas e gramaticais, adotou o nome Allan Kardec — que seu Espírito protetor revelou ter sido seu em existência anterior entre os druidas — para distinguir a obra espírita.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'dificil', true),
(811, 'o_que_e_espiritismo', 'Em que datas foram fundadas por Allan Kardec, respectivamente, a ''Revista Espírita'' e a ''Sociedade Parisiense de Estudos Espíritas''?', '1º de janeiro de 1858 e 1º de abril de 1858.', '18 de abril de 1857 e 1º de janeiro de 1858.', '3 de outubro de 1858 e 25 de dezembro de 1858.', '15 de maio de 1857 e 18 de abril de 1859.', '1º de março de 1859 e 31 de março de 1860.', 'A', 'Allan Kardec lançou o primeiro número da Revista Espírita em 1º de janeiro de 1858 e fundou regularmente a Sociedade Parisiense de Estudos Espíritas em 1º de abril de 1858.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'medio', true),
(812, 'o_que_e_espiritismo', 'Em que data e por qual causa orgânica desencarnou Allan Kardec em Paris, aos 64 anos de idade?', 'Em 18 de abril de 1869, vítima de pneumonia aguda.', 'Em 31 de março de 1869, fulminado pela ruptura de um aneurisma.', 'Em 2 de novembro de 1869, em decorrência de febre tifoide.', 'Em 3 de outubro de 1868, após um acidente vascular em viagem a Lyon.', 'Em 15 de janeiro de 1870, por insuficiência renal crônica.', 'B', 'Em 31 de março de 1869, enquanto preparava a mudança da sede para a rua e passagem Sainte-Anne e entregava um exemplar da Revista Espírita a um caixeiro de livraria, tombou fulminado pela ruptura de um aneurisma.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'medio', true),
(813, 'o_que_e_espiritismo', 'Qual célebre astrônomo francês pronunciou um discurso memorável à beira do túmulo de Allan Kardec, chamando-o de ''o bom senso encarnado''?', 'Urbain Le Verrier.', 'François Arago.', 'Camille Flammarion.', 'Pierre-Simon Laplace.', 'Jean-Baptiste Biot.', 'C', 'No sepultamento de Allan Kardec, o astrônomo Camille Flammarion proferiu vibrante alocução, definindo o Codificador como ''o bom senso encarnado'' e ressaltando o caráter científico do Espiritismo.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'facil', true),
(814, 'o_que_e_espiritismo', 'Qual inscrição sintetizadora da lei de evolução encontra-se gravada no frontão do dólmen de Allan Kardec no cemitério do Père-Lachaise?', 'A fé inabalável é apenas aquela que pode encarar a razão face a face.', 'Fora da caridade não há salvação para o Espírito imortal.', 'Os mortos não morrem: apenas mudam de morada na casa do Pai.', 'Nascer, morrer, renascer ainda e progredir sempre, tal é a lei.', 'Trabalho, solidariedade e tolerância constituem o lema do espírita.', 'D', 'No alto do monumento druídico (dólmen) no cemitério do Père-Lachaise acha-se gravado o postulado fundamental: ''Nascer, morrer, renascer ainda e progredir sempre, tal é a lei''.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'facil', true),
(815, 'o_que_e_espiritismo', 'Segundo o Preâmbulo de ''O Que é o Espiritismo'', qual foi o objetivo principal de Allan Kardec ao publicar este livro sumário?', 'Substituir definitivamente a leitura de O Livro dos Espíritos e de O Livro dos Médiuns.', 'Criar um ritual litúrgico obrigatório para todas as sociedades espíritas da França.', 'Reunir apenas relatos de fenômenos físicos extraordinários para entreter o público.', 'Combater pessoalmente os sacerdotes e cientistas que atacavam sua reputação.', 'Oferecer um resumo sintético dos princípios da Doutrina e responder às principais objeções para quem deseja compreendê-la rapidamente.', 'E', 'No Preâmbulo, Kardec explica que publicou este resumo para dar em poucas palavras uma ideia exata do Espiritismo, fornecendo os pontos cardeais da ciência e respondendo às objeções mais comuns.', 'O Que é o Espiritismo - Preâmbulo', 'medio', true),
(816, 'o_que_e_espiritismo', 'No Capítulo I de ''O Que é o Espiritismo'' (''Pequena conferência espírita''), quais são os três interlocutores com quem o Adeptos dialoga sucessivamente?', 'O Crítico, o Cético e o Padre.', 'O Médico, o Juiz e o Filósofo.', 'O Materialista, o Cientista e o Pastor.', 'O Jornalista, o Magnetizador e o Bispo.', 'O Professor, o Ateo e o Monge.', 'A', 'O Capítulo I é dividido em três diálogos: o Primeiro Diálogo com O Crítico, o Segundo Diálogo com O Cético e o Terceiro Diálogo com O Padre.', 'O Que é o Espiritismo - Cap. I, Pequena conferência espírita', 'facil', true),
(817, 'o_que_e_espiritismo', 'No Primeiro Diálogo (''O Crítico''), que diferença fundamental o Visitante aponta entre a atitude do Crítico e a do Cético?', 'O Crítico crê nos Espíritos, enquanto o Cético acredita apenas em anjos.', 'O Cético duvida, mas busca esclarecer-se; o Crítico julga sem conhecer e procura ridicularizar aquilo que não estudou.', 'O Crítico realiza experiências práticas, enquanto o Cético apenas escreve panfletos.', 'O Cético é sempre inimigo da Ciência, ao passo que o Crítico defende as academias.', 'Não há diferença alguma, pois ambos negam a existência de Deus.', 'B', 'Kardec mostra no diálogo que o Crítico condena a priori e usa a zombaria sem haver lido nem observado nada, ao passo que o Cético sincero apresenta dúvidas racionais e deseja instruir-se.', 'O Que é o Espiritismo - Cap. I, Primeiro Diálogo: O Crítico', 'medio', true),
(818, 'o_que_e_espiritismo', 'No Primeiro Diálogo, quando o Crítico alega que os sábios e as academias oficiais condenaram o Espiritismo, que exemplos históricos o espírita lhe recorda?', 'A aceitação imediata do telégrafo óptico e da imprensa em toda a Europa.', 'A aprovação unânime das descobertas de Newton pela Igreja de Roma.', 'A rejeição inicial de grandes descobertas científicas, como o movimento da Terra por Galileu e a aplicação do vapor por Fulton.', 'O apoio financeiro concedido por Napoleão aos primeiros barcos a vapor.', 'A criação das universidades medievais pelos escolásticos.', 'C', 'Kardec lembra ao Crítico que corporações sábias também rejeitaram ou zombaram de Galileu, de Colombo e de Fulton com o barco a vapor, provando que a verdade independe de decretos acadêmicos.', 'O Que é o Espiritismo - Cap. I, Primeiro Diálogo: O Crítico', 'medio', true),
(819, 'o_que_e_espiritismo', 'Segundo argumenta Kardec no Primeiro Diálogo com o Crítico, qual foi o efeito prático das zombarias e dos ataques da imprensa burlesca contra o Espiritismo?', 'Reduziram drasticamente o número de adeptos nas grandes capitais.', 'Forçaram o fechamento temporário da Sociedade Parisiense de Estudos Espíritas.', 'Impediram a tradução das obras espíritas para outros idiomas europeus.', 'Despertaram a atenção do público, levando milhares de pessoas a examinar a Doutrina e aumentando o número de adeptos.', 'Fizeram com que os médiuns abandonassem a psicografia pelo receio do ridículo.', 'D', 'Kardec demonstra que as críticas levianas funcionaram como propaganda involuntária: aguando a curiosidade pública, fizeram com que pessoas sérias lessem as obras e se tornassem espíritas.', 'O Que é o Espiritismo - Cap. I, Primeiro Diálogo: O Crítico', 'dificil', true),
(820, 'o_que_e_espiritismo', 'Ao responder ao Crítico sobre os casos de charlatanismo e exploração financeira das manifestações, qual é a posição firme da Doutrina Espírita?', 'Tolera a cobrança moderada quando o médium é comprovadamente pobre.', 'Permite sessões pagas desde que a renda seja destinada a hospitais.', 'Autoriza os médiuns profissionais a cobrarem consultas particulares.', 'Reconhece que apenas os fenômenos de efeitos físicos podem ser remunerados.', 'Repudia formalmente qualquer exploração mercantil da mediunidade, declarando que o verdadeiro Espiritismo jamais faz de suas manifestações objeto de lucro.', 'E', 'Kardec enfatiza que o Espiritismo sério condena de modo absoluto os espetáculos pagos e o comércio da mediunidade, não podendo a Ciência verdadeira responder pelos abusos dos charlatães.', 'O Que é o Espiritismo - Cap. I, Primeiro Diálogo: O Crítico', 'dificil', true),
(821, 'o_que_e_espiritismo', 'No início do Segundo Diálogo (''O Cético''), como o espírita recebe a declaração do Visitante de que não crê nos Espíritos, mas deseja compreender a questão?', 'Com simpatia e respeito, pois a dúvida sincera de quem procura instruir-se merece explicação racional.', 'Com indignação, recusando-se a conversar com quem ainda não tem fé.', 'Exigindo que o visitante faça antes um juramento de adesão religiosa.', 'Cobrando uma taxa de matrícula no curso preparatório da Sociedade.', 'Aconselhando-o a desistir, pois a fé espírita só se obtém por graça mística.', 'A', 'Kardec acolhe o Cético com estima, esclarecendo que o Espiritismo não exige fé cega, mas convida ao exame sério, metódico e livre de ideias preconcebidas.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'facil', true),
(822, 'o_que_e_espiritismo', 'No Segundo Diálogo (''O Cético''), como Allan Kardec define de modo claro e direto o que são os Espíritos?', 'São seres angélicos criados à parte da humanidade e que jamais encarnaram.', 'São as próprias almas dos homens que viveram na Terra ou em outros mundos, despojadas de seu envoltório corporal.', 'São emanações magnéticas inconscientes produzidas pelo cérebro dos médiuns.', 'São divindades secundárias encarregadas de governar as forças da natureza.', 'São alucinações coletivas provocadas pelo fluido nervoso dos assistentes.', 'B', 'Kardec explica ao Cético que os Espíritos não são seres abstratos nem uma criação nova: são simplesmente as almas dos homens após a morte do corpo físico.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'facil', true),
(823, 'o_que_e_espiritismo', 'Para demonstrar ao Cético a existência da alma independente da matéria, que argumento fundamental o espírita utiliza?', 'A tradição mitológica dos povos gregos e romanos.', 'A autoridade infalível dos concílios medievais.', 'O fato de que o pensamento, a vontade e o livre-arbítrio são propriedades inteligentes que não podem ser produzidas pela matéria bruta.', 'A semelhança anatômica entre o sistema nervoso humano e o dos vegetais.', 'O cálculo matemático da distância entre as estrelas fixas.', 'C', 'Todo efeito inteligente há de ter uma causa inteligente; como a matéria por si mesma é inerte e desprovida de inteligência, o pensamento humano prova a presença de um princípio espiritual.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'medio', true),
(824, 'o_que_e_espiritismo', 'Segundo explica Kardec ao Cético, de quantos elementos essenciais se compõe o homem encarnado?', 'De dois elementos apenas: o corpo carnal e o fluido elétrico.', 'De quatro elementos: terra, água, ar e fogo.', 'De um único elemento material capaz de produzir o pensamento.', 'De três elementos: o corpo (ser material), a alma (Espírito encarnado) e o perispírito (envoltório semimaterial que une a alma ao corpo).', 'De cinco corpos astrais independentes entre si.', 'D', 'Kardec apresenta a constituição ternária do homem: 1º o corpo físico; 2º a alma ou Espírito; 3º o perispírito, laço fluídico semimaterial que serve de intermediário entre ambos.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'facil', true),
(825, 'o_que_e_espiritismo', 'Quando o Cético pergunta por que uma mesa se move ou responde por pancadas nas sessões de efeitos físicos, o que o espírita lhe esclarece?', 'Que a madeira adquire inteligência própria ao ser magnetizada pelos presentes.', 'Que o movimento resulta exclusivamente da eletricidade terrestre acumulada no móvel.', 'Que todos os movimentos de mesas são produzidos por mecanismos ocultos sob o soalho.', 'Que os Espíritos se transformam materialmente na própria estrutura da mesa.', 'Que a mesa é apenas um instrumento passivo movido pelo Espírito, que combina parte de seu perispírito com o fluido animalizado do médium.', 'E', 'A mesa não pensa nem tem músculos: o Espírito utiliza o fluido próprio do médium combinado ao fluido universal e ao seu perispírito para imprimir movimento ao objeto e dar sinais convencionados.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'medio', true),
(826, 'o_que_e_espiritismo', 'No Segundo Diálogo, por que o uso das mesas falantes e das cestas foi gradualmente substituído pela escrita direta com a mão do médium (psicografia)?', 'Porque a escrita manual direta é o meio mais simples, rápido e cômodo de comunicação, dispensando aparelhos acessórios.', 'Porque as mesas deixaram de girar após o ano de 1856 em toda a Europa.', 'Porque a polícia francesa proibiu a fabricação de cestas-pião e pranchetas.', 'Porque os Espíritos Superiores só conseguem se comunicar por meio de mesas pesadas.', 'Porque a escrita direta impede totalmente a manifestação de Espíritos levianos.', 'A', 'As mesas, cestas e pranchetas eram apenas apêndices do lápis; compreendeu-se logo que o Espírito podia atuar diretamente sobre o braço e a mão do médium, tornando a comunicação muito mais rápida.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'medio', true),
(827, 'o_que_e_espiritismo', 'No diálogo com o Cético, qual é a posição do Espiritismo a respeito do Magnetismo e do Sonambulismo?', 'Considera o magnetismo uma superstição medieval sem qualquer base real.', 'Reconhece-os como ciências irmãs que prepararam o caminho ao demonstrar a ação dos fluidos e a independência da alma.', 'Afirma que o magnetizador só cura quando pronuncia fórmulas cabalísticas.', 'Sustenta que todo médium psicógrafo precisa antes ser magnetizado por um médico.', 'Declara que o fluido magnético destrói a faculdade mediúnica.', 'B', 'Kardec explica que o magnetismo preparou o caminho do Espiritismo, pois o estudo do fluido magnético e da clarividência sonambúlica já demonstrava a ação da alma fora dos sentidos corpóreos.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'dificil', true),
(828, 'o_que_e_espiritismo', 'Que fatos comprovam ao Cético que as comunicações mediúnicas não são simples reflexo das ideias do próprio médium?', 'O fato de o médium usar sempre papel timbrado das sociedades espíritas.', 'A velocidade com que o lápis percorre o papel em linha reta.', 'Comunicações contrárias às opiniões e conhecimentos do médium, em línguas que ele ignora ou até por pessoas analfabetas.', 'O cansaço muscular sentido no braço após duas horas de escrita.', 'A presença obrigatória de sete testemunhas diplomadas na sala.', 'C', 'O Espírito frequentemente trata de assuntos estranhos aos estudos do médium, contradiz suas ideias preconcebidas, revela fatos desconhecidos e por vezes escreve em idiomas que o médium desconhece.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'medio', true),
(829, 'o_que_e_espiritismo', 'Quando o Cético pergunta se basta morrer para que o Espírito saiba tudo e possua toda a sabedoria, o que Kardec responde?', 'Sim, pois a morte rasga imediatamente todos os véus do universo.', 'Sim, desde que o falecido tenha recebido os sacramentos antes de partir.', 'Não, porque após a morte todos os Espíritos perdem a memória para sempre.', 'Não; a morte física não opera transformação miraculosa: o Espírito conserva o grau intelectual e moral que tinha em vida, progredindo gradualmente.', 'Apenas os cientistas conservam a inteligência no mundo espiritual.', 'D', 'Ao deixar o corpo, o homem não se torna instantaneamente sábio nem virtuoso; há no mundo invisível Espíritos de todos os graus de saber e de moralidade.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'facil', true),
(830, 'o_que_e_espiritismo', 'Por que os Espíritos não vêm revelar tesouros ocultos, fórmulas para enriquecer sem trabalho ou invenções prontas para especulação financeira?', 'Porque desconhecem o valor das moedas modernas.', 'Porque estão proibidos de observar a superfície material da Terra.', 'Porque apenas os Espíritos zombeteiros conhecem onde estão os tesouros.', 'Porque perderam toda a capacidade de raciocínio prático ao desencarnar.', 'Porque a lei de Deus impõe ao homem o progresso pelo trabalho e pela pesquisa própria, e os bons Espíritos não servem à cupidez nem ao orgulho.', 'E', 'Os Espíritos Superiores auxiliam o progresso moral e intelectual da humanidade, mas não poupam ao homem o esforço do trabalho; quem busca os Espíritos por interesse material torna-se joguete de mistificadores.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'medio', true),
(831, 'o_que_e_espiritismo', 'No Segundo Diálogo, que resposta o espírita dá à objeção de que o estudo do Espiritismo produziria a loucura?', 'O Espiritismo verdadeiro, longe de produzir a loucura, previne-a e consola as aflições pela fé raciocinada na vida futura e na justiça divina.', 'Admite que metade dos médiuns acaba perdendo a razão após alguns anos.', 'Recomenda que apenas médicos psiquiatras estudem as obras da Codificação.', 'Afirma que a loucura é sempre um castigo físico incurável sem relação com o cérebro.', 'Reconhece que qualquer estudo filosófico ou religioso destrói o sistema nervoso.', 'A', 'Qualquer ideia exagerada em um cérebro já predisposto e enfraquecido pode desencadear delírios (como na política, nas paixões ou no fanatismo religioso), mas o estudo calmo e racional do Espiritismo fortalece a alma contra o desespero.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'medio', true),
(832, 'o_que_e_espiritismo', 'No diálogo com o Cético, por que os fenômenos espíritas não podem ser repetidos à vontade, como uma experiência física ou química de laboratório?', 'Porque os fluidos espirituais evaporam na presença de luz solar.', 'Porque os Espíritos são seres livres e inteligentes, e não máquinas nem reagentes químicos submetidos ao capricho dos observadores.', 'Porque os médiuns perdem suas faculdades diante de mais de três pessoas.', 'Porque a gravidade terrestre anula o perispírito durante o dia.', 'Porque as leis civis proíbem experiências científicas com médiuns.', 'B', 'As ciências físicas operam sobre a matéria inerte que se manipula à vontade; o Espiritismo lida com inteligências livres que têm vontade própria e não se prestam a exigências frívolas de curiosos.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'medio', true),
(833, 'o_que_e_espiritismo', 'Segundo explica Kardec ao Cético, qual foi a utilidade providencial dos fenômenos materiais (mesas girantes e pancadas) no início do Espiritismo?', 'Demonstrar que os Espíritos preferem comunicar-se por objetos de madeira.', 'Substituir definitivamente a imprensa escrita na transmissão dos ensinos morais.', 'Chamar a atenção dos homens pelos sentidos físicos e vencer a incredulidade materialista, servindo de prelúdio ao ensino filosófico.', 'Provar que apenas os Espíritos inferiores podem agir sobre a matéria.', 'Criar uma nova fonte de energia mecânica para a indústria europeia.', 'C', 'Os fenômenos físicos foram o vestíbulo da Ciência: falavam aos olhos para despertar a atenção de uma geração incrédula, abrindo caminho para as comunicações inteligentes e morais.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'dificil', true),
(834, 'o_que_e_espiritismo', 'No Segundo Diálogo, como o espírita explica ao Cético a justiça das desigualdades de aptidões intelectuais e morais que as crianças trazem desde o berço?', 'Pelo acaso genético resultante apenas da alimentação materna.', 'Pelo privilégio arbitrário concedido por Deus a certas almas recém-criadas.', 'Pela influência astrológica da posição dos planetas no instante do parto.', 'Pela preexistência da alma e pela pluralidade das existências (reencarnação), em que cada Espírito traz o patrimônio adquirido em vidas anteriores.', 'Pela transmissão hereditária da própria alma dos pais para os filhos.', 'D', 'Se Deus criasse almas novas a cada nascimento com aptidões tão desiguais, seria parcial; a reencarnação explica que uns já viveram e progrediram mais do que outros em existências precedentes.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'medio', true),
(835, 'o_que_e_espiritismo', 'Quando o Cético pergunta se o Espírito pode retrogradar e reencarnar no corpo de um animal, o que responde a Doutrina Espírita?', 'Sim, como punição temporária para os grandes criminosos da humanidade.', 'Sim, sempre que o homem se entrega aos instintos puramente sensuais.', 'Depende da decisão dos Espíritos Superiores em cada julgamento.', 'Apenas nas espécies domésticas mais próximas do convívio humano.', 'Não; o progresso do Espírito é contínuo: ele pode estacionar, mas jamais retrograda, sendo a metempsicose nos animais contrária à lei divina.', 'E', 'Kardec distingue claramente a reencarnação espírita da antiga metempsicose: o Espírito humano nunca volta a ser animal; se estaciona, reencarna em condições humanas de expiação para avançar.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'medio', true),
(836, 'o_que_e_espiritismo', 'No Segundo Diálogo, todas as reencarnações do Espírito ocorrem exclusivamente no planeta Terra?', 'Não; a Terra é apenas um dos numerosos mundos habitados, e as reencarnações ocorrem em diferentes globos conforme o adiantamento do Espírito.', 'Sim, pois a Terra é o único planeta habitado do universo.', 'Sim, porque o perispírito humano não suporta a atmosfera de outros orbes.', 'Não, pois cada Espírito só encarna uma única vez na Terra e nunca mais retorna.', 'Apenas os Espíritos perfeitos reencarnam na Lua e no Sol.', 'A', 'As diversas existências corporais podem realizar-se na Terra ou em outros mundos materiais mais ou menos adiantados, segundo a máxima evangélica de que ''há muitas moradas na casa de meu Pai''.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'facil', true),
(837, 'o_que_e_espiritismo', 'Ao final do Segundo Diálogo, que tríplice efeito moral produz no homem a convicção profunda das verdades ensinadas pelo Espiritismo?', 'Isolamento monástico, desprezo pela ciência e temor constante da morte.', 'Paciência e resignação nas provas da vida, afastamento do suicídio e prática sincera da caridade e fraternidade.', 'Ambição política, orgulho intelectual e busca de privilégios sociais.', 'Indiferença diante do sofrimento alheio, fatalismo passivo e ociosidade.', 'Crença na salvação exclusiva por fórmulas exteriores e rituais.', 'B', 'Compreendendo que a vida terrestre é breve estação de aprendizado, o homem encara a morte sem pavor, suporta as vicissitudes com coragem, repele o suicídio e esforça-se no bem.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'medio', true),
(838, 'o_que_e_espiritismo', 'No Terceiro Diálogo (''O Padre''), como o espírita responde à afirmação eclesiástica de que apenas o demônio e seus anjos decaídos podem comunicar-se com os homens?', 'Concordando que as almas humanas permanecem adormecidas até o juízo final.', 'Afirmando que os maus Espíritos não existem no plano espiritual.', 'Mostrando que seria absurdo e contrário à bondade de Deus conceder liberdade de ação apenas ao espírito do mal e proibir as boas almas de consolar e instruir os vivos.', 'Dizendo que os Espíritos só se comunicam dentro dos templos consagrados.', 'Alegando que o Antigo e o Novo Testamento jamais mencionam manifestações espirituais.', 'C', 'Kardec argumenta com lógica irrefutável: se Deus permite que os maus Espíritos tentem os homens, com muito mais razão permite que os bons Espíritos venham ampará-los e encaminhá-los ao bem.', 'O Que é o Espiritismo - Cap. I, Terceiro Diálogo: O Padre', 'medio', true),
(839, 'o_que_e_espiritismo', 'No Terceiro Diálogo com o Padre, qual é o critério seguro apontado pelo Espiritismo para distinguir se um Espírito comunicante é bom ou mau?', 'O nome famoso ou sagrado com que ele assina a mensagem.', 'A beleza caligráfica da escrita psicografada pelo médium.', 'A intensidade das pancadas ou o peso da mesa que se levanta.', 'A qualidade moral de sua linguagem e de seus conselhos, pois ''reconhece-se a árvore pelo fruto'': um Espírito que só ensina a caridade e o bem não pode ser mau.', 'O horário noturno ou diurno em que ocorre a reunião mediúnica.', 'D', 'Aplicando a máxima de Jesus (''Pelos seus frutos os conhecereis''), Kardec lembra que o demônio não poderia pregar o amor a Deus, o perdão das ofensas, a humildade e a caridade sem destruir seu próprio reino.', 'O Que é o Espiritismo - Cap. I, Terceiro Diálogo: O Padre', 'facil', true),
(840, 'o_que_e_espiritismo', 'Quando o Padre cita a proibição mosaica de interrogar os mortos (Deuteronômio), que explicação histórica e doutrinária o espírita apresenta?', 'Que Moisés desconhecia totalmente a existência da alma imortal.', 'Que o texto bíblico foi inventado apenas no século XVIII.', 'Que Moisés proibiu apenas a escrita manual, mas permitiu as mesas girantes.', 'Que a lei mosaica só se aplicava aos sacerdotes egípcios e babilônios.', 'Que Moisés reprimiu o abuso supersticioso da adivinhação mercenária e idólatra entre os hebreus, e que essa própria proibição prova que a comunicação com os mortos era real.', 'E', 'Não se proíbe aquilo que não existe: Moisés vetou a evocação transformada em ofício de adivinhação e comércio supersticioso, ao passo que o Espiritismo condena esses mesmos abusos e busca a edificação moral.', 'O Que é o Espiritismo - Cap. I, Terceiro Diálogo: O Padre', 'medio', true),
(841, 'o_que_e_espiritismo', 'No Terceiro Diálogo, o que o espírita responde quando o Padre afirma que a religião já ensina tudo e que a humanidade não precisa de novas luzes espirituais?', 'Se os ensinos tradicionais bastassem na forma como foram interpretados, não haveria tantos incrédulos e materialistas, os quais o Espiritismo reconduz a Deus pela prova experimental.', 'Que a ciência moderna deve abolir toda forma de sentimento religioso.', 'Que o Evangelho de Jesus tornou-se obsoleto diante da filosofia moderna.', 'Que o Espiritismo veio instituir um novo sacerdócio hierárquico na Europa.', 'Que apenas os teólogos podem compreender as leis morais do universo.', 'A', 'O Espiritismo não vem destruir os princípios fundamentais da religião nem a moral do Cristo, mas combater o materialismo fornecendo provas palpáveis da sobrevivência da alma.', 'O Que é o Espiritismo - Cap. I, Terceiro Diálogo: O Padre', 'medio', true),
(842, 'o_que_e_espiritismo', 'No diálogo com o Padre, qual é o ponto em que a Doutrina Espírita diverge do dogma teológico das penas eternas e de um inferno material de fogo?', 'O Espiritismo nega que o culpado sofra qualquer consequência após a morte.', 'Os Espíritos ensinam que as penas são morais e proporcionais às faltas, mas nunca perpétuas, pois Deus jamais fecha ao arrependimento a porta da regeneração.', 'A Doutrina Espírita afirma que o sofrimento dura exatamente sete anos para todos os Espíritos.', 'O Espiritismo ensina que os Espíritos criminosos são aniquilados no momento do desencarne.', 'Kardec sustenta que apenas as preces pagas podem libertar uma alma sofredora.', 'B', 'A condenação irrevogável e eterna é incompatível com a infinita justiça e bondade de Deus; o Espírito culpado sofre nas trevas morais de sua consciência até arrepender-se e reparar o mal por novas provas.', 'O Que é o Espiritismo - Cap. I, Terceiro Diálogo: O Padre', 'medio', true),
(843, 'o_que_e_espiritismo', 'Segundo o Capítulo II (''Noções elementares de Espiritismo'', itens 1 a 8), qual é a grande missão prática do Espiritismo perante o mundo moderno?', 'Substituir as ciências exatas por revelações místicas.', 'Formar uma corporação política para governar as nações.', 'Combater a incredulidade e o materialismo pela prova dos fatos e regenerar a humanidade pela aplicação da moral evangélica.', 'Ensinar processos mágicos para evitar as doenças do corpo físico.', 'Descobrir minas de ouro e pedras preciosas por meio de sonâmbulos.', 'C', 'Nos itens iniciais do Capítulo II, Kardec destaca que o Espiritismo é o mais poderoso antagonista do materialismo e tem por fim o melhoramento moral da humanidade.', 'O Que é o Espiritismo - Cap. II, itens 1 a 8', 'facil', true),
(844, 'o_que_e_espiritismo', 'De acordo com o Capítulo II (itens 13 a 16), de onde os Espíritos tiram o seu envoltório semimaterial denominado perispírito?', 'Dos átomos metálicos do núcleo terrestre.', 'Do oxigênio respirado nos primeiros dias após o nascimento.', 'Da imaginação criadora dos médiuns videntes.', 'Do fluido universal de cada globo, razão pela qual a natureza do perispírito varia conforme o mundo em que o Espírito habita.', 'Da decomposição química dos alimentos ingeridos pelo corpo.', 'D', 'O Espírito extrai o seu perispírito do fluido cósmico universal próprio de cada mundo; por isso, ao mudar de mundo, muda esse envoltório como quem troca de vestimenta.', 'O Que é o Espiritismo - Cap. II, itens 13 a 16', 'facil', true),
(845, 'o_que_e_espiritismo', 'No Capítulo II (itens 17 a 23), ao tratar das diversas ordens de Espíritos, como Allan Kardec sintetiza as três categorias principais da escala espírita?', 'Querubins, Serafins e Arcanjos.', 'Sábios, Guerreiros e Artistas.', 'Visíveis, Invisíveis e Tangíveis.', 'Antigos, Medievais e Modernos.', 'Espíritos imperfeitos (predomínio da matéria sobre o espírito), bons Espíritos (predomínio do espírito sobre a matéria, desejo do bem) e Espíritos puros (perfeição absoluta).', 'E', 'Embora a transição entre os graus seja insensível, Kardec resume a classificação em Espíritos imperfeitos (inclinados ao mal ou levianos), bons Espíritos e Espíritos puros ou superiores.', 'O Que é o Espiritismo - Cap. II, itens 17 a 23', 'facil', true),
(846, 'o_que_e_espiritismo', 'Segundo o Capítulo II (itens 21 e 22), que tipos de Espíritos compõem a classe dos chamados Espíritos levianos, zombeteiros e pseudossábios?', 'Espíritos imperfeitos que, sem serem essencialmente maus, comprazem-se em mistificar, intrigar ou ostentar falso saber com linguagem pomposa.', 'Espíritos puros que testam a paciência dos médiuns por meio de mentiras.', 'Almas de crianças desencarnadas que jamais atingirão a maturidade intelectual.', 'Entidades não humanas criadas exclusivamente para habitar as florestas.', 'Espíritos superiores encarregados de punir os cientistas orgulhosos.', 'A', 'Nos itens 21 e 22, Kardec descreve os Espíritos levianos, ignorantes e zombeteiros, que se intrometem em tudo e respondem sem saber, bem como os pseudossábios, cheios de orgulho e sistemas falsos.', 'O Que é o Espiritismo - Cap. II, itens 21 e 22', 'medio', true),
(847, 'o_que_e_espiritismo', 'Conforme o Capítulo II (itens 25 a 29), qual é a diferença entre manifestações ocultas e manifestações ostensivas dos Espíritos?', 'As ocultas ocorrem apenas à meia-noite e as ostensivas ao meio-dia.', 'As ocultas dão-se pela inspiração invisível no pensamento (sugestões da consciência), enquanto as ostensivas produzem-se por efeitos apreciáveis aos sentidos ou pela mediunidade.', 'As ocultas são sempre produzidas por maus Espíritos e as ostensivas apenas por anjos.', 'As ocultas exigem aparelhos elétricos e as ostensivas dispensam médiuns.', 'Não existe diferença real entre ambas na classificação de Allan Kardec.', 'B', 'A ação oculta ocorre quando os Espíritos nos inspiram pensamentos e conselhos sem que o percebamos; a ação ostensiva ou patente se dá pela escrita, fala, visão, audição ou fenômenos físicos.', 'O Que é o Espiritismo - Cap. II, itens 25 a 29', 'facil', true),
(848, 'o_que_e_espiritismo', 'De acordo com o Capítulo II (itens 30 a 35), que são as manifestações espontâneas e as manifestações provocadas?', 'Espontâneas são as obtidas por médiuns pagos; provocadas são as gratuitas.', 'Espontâneas são as escritas em verso; provocadas são as escritas em prosa.', 'Espontâneas ocorrem sem que ninguém chame o Espírito; provocadas dão-se por meio da evocação ou do concurso intencional dos médiuns.', 'Espontâneas acontecem apenas no sono; provocadas acontecem em vigília.', 'Espontâneas são exclusivas das crianças; provocadas pertencem aos idosos.', 'C', 'Kardec explica que muitas vezes os Espíritos se manifestam espontaneamente (por ruídos, aparições ou comunicações não solicitadas), mas também podem ser chamados por evocação.', 'O Que é o Espiritismo - Cap. II, itens 30 a 35', 'medio', true),
(849, 'o_que_e_espiritismo', 'Segundo o Capítulo II (itens 36 a 39), qual é o fim providencial das manifestações espíritas na atualidade?', 'Satisfazer a curiosidade fútil dos salões mundanos.', 'Substituir a medicina, a engenharia e a jurisprudência.', 'Prever o futuro detalhado de cada indivíduo para livrá-lo de provas.', 'Convencer os homens da existência e imortalidade da alma e da justiça futura, conduzindo-os ao aperfeiçoamento moral.', 'Restaurar os antigos oráculos pagãos da Grécia e do Egito.', 'D', 'Deus permite as manifestações para esclarecer a humanidade numa época de dúvida, provando que tudo não acaba com a morte do corpo e que colhemos na vida futura o fruto de nossas obras.', 'O Que é o Espiritismo - Cap. II, itens 36 a 39', 'facil', true),
(850, 'o_que_e_espiritismo', 'No Capítulo II (itens 40 a 47), como são denominados no Espiritismo os médiuns que escrevem sob a influência dos Espíritos?', 'Médiuns tiptólogos.', 'Médiuns videntes.', 'Médiuns audientes.', 'Médiuns de efeitos físicos.', 'Médiuns escreventes ou psicógrafos.', 'E', 'No item 45, Allan Kardec define os médiuns escreventes ou psicógrafos como aqueles que têm a faculdade de escrever por si mesmos sob a influência dos Espíritos.', 'O Que é o Espiritismo - Cap. II, item 45', 'facil', true),
(851, 'o_que_e_espiritismo', 'Segundo o Capítulo II (itens 46 a 49), qual é a diferença entre os médiuns psicógrafos mecânicos, semimecânicos e intuitivos?', 'No mecânico a mão move-se sem consciência do que escreve; no intuitivo o Espírito atua sobre o pensamento do médium; no semimecânico há impulso na mão acompanhado de consciência das palavras.', 'O mecânico usa máquinas de escrever; o intuitivo usa cestas; o semimecânico usa ardósias.', 'O mecânico só recebe Espíritos inferiores; o intuitivo só recebe Espíritos puros.', 'O mecânico escreve dormindo; o intuitivo escreve em transe cataléptico.', 'Não há distinção alguma entre os três modos de psicografia.', 'A', 'No médium mecânico o Espírito move diretamente a mão sem que o médium tenha consciência do escrito; no intuitivo transmite o pensamento; no semimecânico participam ambos os mecanismos.', 'O Que é o Espiritismo - Cap. II, itens 46 a 49', 'medio', true),
(852, 'o_que_e_espiritismo', 'De acordo com o Capítulo II (itens 41 a 44), como se caracterizam os médiuns de efeitos físicos, os audientes, os falantes e os videntes?', 'São graus hierárquicos de sacerdócio dentro das sociedades espíritas.', 'Pelos diferentes modos de percepção ou ação: produzem fenômenos materiais (ruídos, movimentos), ouvem os Espíritos, falam sob sua ação ou os veem em estado de vigília.', 'São faculdades exclusivas de pessoas que nasceram cegas ou surdas.', 'Referem-se apenas aos fenômenos de sonambulismo provocado por hipnose.', 'Designam médiuns que atuam somente uma vez na vida.', 'B', 'Kardec classifica as variedades de médiuns segundo os efeitos: efeitos físicos, sensitivos ou impressionáveis, audientes, falantes, videntes, sonâmbulos, curadores, pneumatógrafos e psicógrafos.', 'O Que é o Espiritismo - Cap. II, itens 41 a 44', 'facil', true),
(853, 'o_que_e_espiritismo', 'No Capítulo II (item 44), que nome específico Allan Kardec dá à faculdade raríssima de obter a escrita direta traçada pelos próprios Espíritos sem o uso da mão do médium?', 'Tiptologia alfabética.', 'Psicofonia consciente.', 'Pneumatografia (e pneumatofonia para os sons articulados no ar).', 'Clariaudiência intuitiva.', 'Bicorporeidade tangível.', 'C', 'Kardec denomina pneumatografia a escrita direta produzida pelos Espíritos sem intermediário manual, advertindo também contra as fraudes dos que simulam esse fenômeno.', 'O Que é o Espiritismo - Cap. II, item 44', 'dificil', true),
(854, 'o_que_e_espiritismo', 'Segundo o Capítulo II (''Escolhos da mediunidade'', itens 55 a 64), qual é o maior perigo que ameaça os médiuns e pode levá-los à obsessão e à perda da assistência dos bons Espíritos?', 'O estudo constante das obras fundamentais da Codificação.', 'A prática gratuita da caridade em benefício dos enfermos.', 'O hábito de fazer preces antes das reuniões mediúnicas.', 'O orgulho, a presunção de infalibilidade e a fascinação exercida por Espíritos enganadores que lisonjeiam a vaidade do médium.', 'A leitura comparada das comunicações em grupos sérios.', 'D', 'O orgulho é a pedra de toque: quando o médium se julga privilegiado e infalível, afasta os bons Espíritos e entrega-se aos Espíritos mistificadores e fascinadores.', 'O Que é o Espiritismo - Cap. II, itens 55 a 64', 'medio', true),
(855, 'o_que_e_espiritismo', 'De acordo com o Capítulo II (''Qualidades dos médiuns'', itens 65 a 71), o que atrai os bons Espíritos para junto de um médium?', 'A riqueza material e os títulos acadêmicos do médium.', 'A força física muscular e o temperamento sanguíneo.', 'O uso de talismãs, vestes especiais e incensos.', 'A cobrança de honorários elevados pelas sessões.', 'As qualidades morais do médium: bondade, benevolência, simplicidade de coração, humildade, devotamento e amor ao bem.', 'E', 'A faculdade mediúnica em si é orgânica e independe da moral, mas o seu bom uso e a assistência dos bons Espíritos dependem essencialmente das qualidades morais do médium.', 'O Que é o Espiritismo - Cap. II, itens 65 a 71', 'facil', true),
(856, 'o_que_e_espiritismo', 'No Capítulo II (''Charlatanismo'', itens 72 a 81), por que Allan Kardec afirma que o desinteresse material absoluto é a mais segura garantia contra o charlatanismo mediúnico?', 'Porque onde não há lucro nem especulação não há interesse em simular fenômenos, e os Espíritos Superiores não se prestam a exibições mercantis.', 'Porque os Espíritos cobram tributos espirituais em moedas antigas.', 'Porque a lei francesa proibia apenas as reuniões gratuitas.', 'Porque os médiuns gratuitos jamais precisam estudar a Doutrina.', 'Porque o dinheiro destrói quimicamente o fluido magnético humano.', 'A', 'Os Espíritos não estão à disposição de quem paga; um médium que explorasse sua faculdade precisaria simular fenômenos quando os Espíritos não quisessem comparecer, caindo na fraude.', 'O Que é o Espiritismo - Cap. II, itens 72 a 81', 'medio', true),
(857, 'o_que_e_espiritismo', 'Segundo o Capítulo II (''Identidade dos Espíritos'', itens 82 a 89), por que não devemos aceitar cegamente os grandes nomes venerados com que certos Espíritos assinam suas comunicações?', 'Porque nenhum Espírito elevado jamais se comunicou com a Terra.', 'Porque Espíritos mistificadores e orgulhosos frequentemente usurpam nomes respeitáveis para impor ideias absurdas ou apócrifas.', 'Porque os Espíritos esquecem todos os nomes próprios após a morte.', 'Porque apenas os Espíritos familiares possuem nome no mundo espiritual.', 'Porque a escrita mediúnica altera automaticamente as letras da assinatura.', 'B', 'A identidade dos Espíritos antigos ou ilustres não se prova pelo nome assinado, mas pela elevação constante das ideias, pureza moral, ausência de contradições e gravidade da linguagem.', 'O Que é o Espiritismo - Cap. II, itens 82 a 89', 'medio', true),
(858, 'o_que_e_espiritismo', 'No Capítulo II (''Contradições'', itens 90 a 97), qual é a causa principal das aparentes contradições encontradas em certas comunicações espíritas?', 'A variação climática entre os hemisférios norte e sul.', 'A instabilidade do fluido cósmico universal durante os eclipses.', 'A diversidade de graus de saber e moralidade entre os Espíritos comunicantes, pois cada um fala segundo seus conhecimentos e opiniões pessoais.', 'A falta de dicionários padronizados nas escolas europeias.', 'O defeito de fabricação dos lápis utilizados nas sessões.', 'C', 'Nem todos os Espíritos sabem tudo: os Espíritos inferiores ou pseudossábios emitem sistemas pessoais e opiniões divergentes, ao passo que os Espíritos Superiores estão sempre de acordo quanto ao ensino moral e fundamental.', 'O Que é o Espiritismo - Cap. II, itens 90 a 97', 'dificil', true),
(859, 'o_que_e_espiritismo', 'De acordo com o Capítulo II (itens 95 a 97), que método de controle Allan Kardec estabeleceu para distinguir a verdade do erro no ensino dos Espíritos?', 'Aceitar exclusivamente as comunicações de um único médium parisiense.', 'Submeter todas as mensagens à votação política das câmaras municipais.', 'Rejeitar qualquer comunicação que trate de filosofia ou moral.', 'O controle da razão aliado à concordância universal do ensino dado pelos Espíritos em diferentes lugares por múltiplos médiuns desconhecidos entre si.', 'Realizar sorteios semanais entre as mensagens psicografadas.', 'D', 'Kardec apoiou a Codificação na concordância geral do ensino dos Espíritos através de numerosos médiuns em diversos países e no exame rigoroso da lógica e do bom senso.', 'O Que é o Espiritismo - Cap. II, itens 95 a 97', 'medio', true),
(860, 'o_que_e_espiritismo', 'Segundo o Capítulo II (''Consequências do Espiritismo'', itens 98 a 104), qual é o critério pelo qual se reconhece o verdadeiro espírita?', 'Pela faculdade de mover objetos pesados sem contato físico.', 'Pelo número de livros espíritas que guarda em sua biblioteca.', 'Pelo uso de insígnias exteriores e fórmulas místicas de saudação.', 'Pela capacidade de adivinhar a sorte e o futuro das pessoas.', 'Pela sua transformação moral e pelos esforços que emprega para domar suas más inclinações, praticando a caridade por pensamentos, palavras e obras.', 'E', 'Crer apenas nos fenômenos faz o crente ou simpatizante; o verdadeiro espírita é o que aplica a moral da Doutrina para reformar-se intimamente e ser mais benevolente e caridoso.', 'O Que é o Espiritismo - Cap. II, itens 98 a 104', 'facil', true),
(861, 'o_que_e_espiritismo', 'No início do Capítulo III (''Solução de alguns problemas pela Doutrina Espírita'', item 105), o que ensina o Espiritismo sobre a pluralidade dos mundos?', 'Que todos os globos que circulam no espaço são habitados por seres apropriados à constituição física de cada mundo.', 'Que apenas a Terra e Marte possuem seres vivos inteligentes.', 'Que os astros são apenas pontos luminosos criados para enfeitar a noite terrestre.', 'Que os demais planetas só serão habitados após a destruição da Terra.', 'Que a vida espiritual não pode existir fora da atmosfera terrestre.', 'A', 'No item 105, Kardec expõe que todos os mundos que gravitam no espaço são habitados e apresentam diferentes graus de adiantamento físico e moral.', 'O Que é o Espiritismo - Cap. III, item 105', 'facil', true),
(862, 'o_que_e_espiritismo', 'Segundo o Capítulo III (itens 106 e 107), qual é a posição da Terra na hierarquia dos mundos habitados?', 'É o mundo mais atrasado e primitivo de todo o universo.', 'Não está na primeira nem na última linha, mas é um dos mundos menos adiantados, onde ainda predominam as provas, expiações e necessidades materiais.', 'É um mundo celeste onde só habitam Espíritos puros.', 'É o único globo onde existe o livre-arbítrio humano.', 'É um planeta superior a Júpiter em evolução moral e física.', 'B', 'Kardec esclarece que a Terra não ocupa nem o primeiro nem o último degrau, mas pertence à categoria dos mundos onde a imperfeição moral e as vicissitudes corporais ainda exigem duro trabalho e expiação.', 'O Que é o Espiritismo - Cap. III, itens 106 e 107', 'medio', true),
(863, 'o_que_e_espiritismo', 'De acordo com o Capítulo III (''Do homem durante a vida terrestre'', itens 108 a 111), em que momento se completa a união definitiva da alma com o corpo?', 'Apenas aos sete anos de idade, quando começa a razão.', 'Três meses após o batismo religioso da criança.', 'Começa na concepção e só é completa no instante do nascimento.', 'Somente quando o jovem atinge a maioridade civil.', 'Apenas no momento da desencarnação do corpo físico.', 'C', 'No item 110, Kardec precisa que a união da alma com o corpo começa na concepção, mas só se torna completa no momento do nascimento.', 'O Que é o Espiritismo - Cap. III, item 110', 'medio', true),
(864, 'o_que_e_espiritismo', 'Segundo o Capítulo III (itens 112 e 113), o que ocorre com a alma durante o sono do corpo físico?', 'A alma adormece profundamente e perde toda a atividade consciente.', 'O perispírito dissolve-se temporariamente até o despertar matinal.', 'O Espírito desencarna definitivamente e outro Espírito ocupa o corpo.', 'Os laços que a prendem ao corpo afrouxam-se e a alma recobra parte de sua liberdade, entrando em relação com outros Espíritos nos sonhos.', 'A alma permanece aprisionada exclusivamente dentro do coração.', 'D', 'Enquanto o corpo repousa, o Espírito não precisa de descanso: afrouxam-se os laços fluídicos, ele percorre o espaço e comunica-se com encarnados e desencarnados, originando muitas lembranças de sonhos.', 'O Que é o Espiritismo - Cap. III, itens 112 e 113', 'medio', true),
(865, 'o_que_e_espiritismo', 'Conforme o Capítulo III (''A alma antes da união com o corpo'', itens 114 e 115), como Deus cria todos os Espíritos?', 'Uns já sábios e virtuosos, e outros predestinados ao mal.', 'Dotados desde o primeiro dia de toda a ciência universal.', 'Divididos em castas eternas que jamais se misturam.', 'Formados a partir da divisão da alma dos próprios pais.', 'Simples e ignorantes, isto é, sem ciência e sem conhecimento do bem e do mal, mas com igual aptidão para tudo adquirir pelo esforço próprio.', 'E', 'Deus, soberanamente justo, não privilegia nenhum Espírito na criação: todos partem do mesmo ponto inicial — simples e ignorantes — e conquistam a perfeição pelo trabalho e livre-arbítrio.', 'O Que é o Espiritismo - Cap. III, itens 114 e 115', 'facil', true),
(866, 'o_que_e_espiritismo', 'Segundo o Capítulo III (itens 116 a 119), o que faz o Espírito quando abusa de seu livre-arbítrio e retarda seu adiantamento?', 'Sofre as consequências de suas faltas e precisa recomeçar em novas existências corporais a tarefa que desempenhou mal.', 'É condenado ao fogo eterno sem possibilidade de reparação.', 'Regressa à condição de mineral ou vegetal.', 'Perde a individualidade e dissolve-se no fluido cósmico.', 'Recebe o perdão automático no instante da morte sem precisar progredir.', 'A', 'Não podendo ir para os mundos felizes sem haver-se depurado, o Espírito estacionário ou culpado reencarna em mundos de provas e expiações para reparar o tempo perdido.', 'O Que é o Espiritismo - Cap. III, itens 116 a 119', 'medio', true),
(867, 'o_que_e_espiritismo', 'De acordo com o Capítulo III (''A alma após a morte'', itens 120 a 123), a alma conserva a sua individualidade após a morte do corpo?', 'Não, pois mergulha no todo universal como uma gota d''água no oceano.', 'Sim; jamais a perde, conservando a consciência de si mesma e o envoltório etéreo (perispírito), que reproduz a forma humana.', 'Conserva a individualidade apenas durante quarenta dias após o enterro.', 'Somente os grandes gênios mantêm a memória individual após a morte.', 'A alma divide-se em várias centelhas inconscientes.', 'B', 'Sem individualidade e consciência de si mesma, a sobrevivência seria equivalente ao nada; o Espírito leva consigo o perispírito, sua memória, seus afetos, suas luzes ou sua ignorância.', 'O Que é o Espiritismo - Cap. III, itens 120 a 123', 'facil', true),
(868, 'o_que_e_espiritismo', 'Segundo o Capítulo III (itens 124 a 127), de que depende a duração e a intensidade da perturbação que se segue à morte?', 'Da riqueza do mausoléu construído pela família na Terra.', 'Da idade cronológica do corpo físico no instante do óbito.', 'Da elevação moral do Espírito e do seu grau de desapego das coisas materiais.', 'Da estação do ano e da fase da Lua no dia do desencarne.', 'Do número de velas acesas ao redor do féretro.', 'C', 'Para o homem de consciência pura, que já se desligou dos interesses terrenos durante a vida, o despertar espiritual é rápido e calmo; para o materialista e o culpado, a perturbação é longa e penosa.', 'O Que é o Espiritismo - Cap. III, itens 124 a 127', 'medio', true),
(869, 'o_que_e_espiritismo', 'No Capítulo III (''Estado dos Espíritos'', itens 128 a 132), como são chamados os Espíritos que se encontram no intervalo entre duas existências corporais?', 'Espíritos elementais.', 'Espíritos cristalizados.', 'Espíritos incriados.', 'Espíritos errantes (no estado de erraticidade).', 'Espíritos anônimos.', 'D', 'No item 128, Kardec explica que no intervalo de suas existências corporais os Espíritos estão no estado de erraticidade e são denominados Espíritos errantes.', 'O Que é o Espiritismo - Cap. III, item 128', 'facil', true),
(870, 'o_que_e_espiritismo', 'De acordo com o Capítulo III (itens 129 e 130), todos os Espíritos desencarnados permanecem errantes indefinidamente?', 'Sim, todos os Espíritos continuam errantes por toda a eternidade.', 'Sim, pois nenhum Espírito jamais fica livre da reencarnação.', 'Não, porque após três séculos os Espíritos deixam de existir.', 'Apenas os Espíritos inferiores deixam de ser errantes.', 'Não; os Espíritos puros, que atingiram a perfeição e não precisam mais de novas reencarnações, não são mais errantes, pois seu estado é definitivo.', 'E', 'O estado errante é transitório e próprio dos Espíritos que ainda têm de reencarnar para progredir; os Espíritos puros já chegaram ao termo da escala e gozam da felicidade definitiva.', 'O Que é o Espiritismo - Cap. III, itens 129 e 130', 'medio', true),
(871, 'o_que_e_espiritismo', 'Segundo o Capítulo III (''Penas e gozos futuros'', itens 133 a 137), qual é a natureza das penas e das alegrias da alma na vida espiritual?', 'São essencialmente morais e inerentes ao grau de elevação ou de imperfeição do próprio Espírito, que carrega em si mesmo o seu céu ou o seu inferno.', 'Consistem em torturas físicas produzidas por caldeiras e chamas materiais.', 'Resumem-se na contemplação imóvel e ociosa sem qualquer atividade útil.', 'Dependem exclusivamente da posição social que o indivíduo ocupou na Terra.', 'São iguais para todos os Espíritos, independentemente de suas obras.', 'A', 'Não tendo mais corpo carnal, o Espírito não sofre torturas físicas exteriores: a felicidade nasce da pureza, do amor e das missões úteis, enquanto o sofrimento decorre do remorso, das paixões não saciadas e da visão de suas vítimas.', 'O Que é o Espiritismo - Cap. III, itens 133 a 137', 'medio', true),
(872, 'o_que_e_espiritismo', 'Conforme o Capítulo III (item 136), onde estão localizados o céu e o inferno segundo a Doutrina Espírita?', 'O céu fica acima das estrelas fixas e o inferno no centro incandescente da Terra.', 'Em toda parte: o céu está onde há Espíritos felizes e mundos superiores; o inferno está no próprio íntimo dos Espíritos imperfeitos e nos mundos de expiação.', 'O céu localiza-se no Sol e o inferno na superfície da Lua.', 'Ambos são lugares circunscritos cercados por muralhas intransponíveis.', 'Existem apenas como figuras poéticas sem correspondência com o estado da alma.', 'B', 'O céu e o inferno não são lugares geograficamente circunscritos: o Espírito feliz leva consigo a ventura onde quer que esteja, e o Espírito perverso ou impenitente carrega em si mesmo o seu tormento.', 'O Que é o Espiritismo - Cap. III, item 136', 'medio', true),
(873, 'o_que_e_espiritismo', 'De acordo com o Capítulo III (item 137), a que corresponde na Doutrina Espírita a ideia tradicional do purgatório?', 'A um vale escuro onde as almas aguardam passivamente o fim do mundo.', 'A uma prisão subterrânea onde se paga resgate em moedas.', 'Ao estado de erraticidade dolorosa e às encarnações corporais expiatórias em que o Espírito se depura de suas imperfeições.', 'Ao sono letárgico dos Espíritos que desencarnaram na infância.', 'À perda temporária da inteligência nos mundos inferiores.', 'C', 'Kardec explica no item 137 que o purgatório é uma realidade moral: consiste nas dores da erraticidade e nas existências terrestres de prova e expiação pelas quais nos purificamos.', 'O Que é o Espiritismo - Cap. III, item 137', 'facil', true),
(874, 'o_que_e_espiritismo', 'Segundo o Capítulo III (''Intervenção dos Espíritos no mundo corporal'', itens 138 a 143), o que é o Espírito protetor ou Anjo de guarda?', 'Um Espírito inferior encarregado de vigiar os bens materiais da família.', 'Uma força magnética impessoal gerada pelo pensamento humano.', 'Um Espírito que anula o livre-arbítrio do protegido para impedi-lo de errar.', 'Um Espírito de ordem elevada ligado ao indivíduo desde o nascimento para guiá-lo no caminho do bem por meio de bons conselhos.', 'Apenas uma figura alegórica sem existência real no plano espiritual.', 'D', 'Todo homem tem um Espírito protetor (anjo guardião ou bom gênio) de natureza superior, que o assiste com inspirações salutares sem jamais suprimir o seu livre-arbítrio.', 'O Que é o Espiritismo - Cap. III, itens 140 e 141', 'facil', true),
(875, 'o_que_e_espiritismo', 'De acordo com o Capítulo III (itens 142 e 143), qual é o meio mais eficaz de afastar os maus Espíritos e atrair a assistência dos bons?', 'Pronunciar fórmulas latinas de exorcismo e queimar ervas aromáticas.', 'Traçar sinais cabalísticos nas portas e janelas da residência.', 'Evitar qualquer conversa sobre assuntos espirituais ou filosóficos.', 'Portar amuletos metálicos magnetizados por sonâmbulos.', 'Praticar o bem, confiar em Deus, elevar o pensamento pela prece sincera e vencer as próprias imperfeições morais.', 'E', 'Os maus Espíritos são atraídos pelas nossas próprias paixões (orgulho, egoísmo, ódio, cobiça); nenhuma fórmula exterior os afasta se o homem não se reformar moralmente.', 'O Que é o Espiritismo - Cap. III, itens 142 e 143', 'facil', true),
(876, 'o_que_e_espiritismo', 'Segundo o Capítulo III (''Causas anteriores das aflições'', itens 144 a 148), onde reside a causa da maioria das aflições terrenas?', 'Na própria conduta imprudente, orgulhosa ou egoísta do homem na vida presente; e, quando não têm causa atual, nas faltas cometidas em existências anteriores.', 'Na fatalidade cega do destino contra a qual o homem nada pode fazer.', 'No pecado original cometido por um único casal no início dos tempos.', 'Na influência maléfica dos cometas sobre a atmosfera terrestre.', 'No capricho arbitrário da Providência ao distribuir dores sem motivo.', 'A', 'Kardec distingue duas fontes de aflições: 1ª as que o homem cria nesta própria vida por sua imprevidência e más paixões; 2ª as que atingem o homem de bem sem causa atual aparente, que são expiações de vidas passadas.', 'O Que é o Espiritismo - Cap. III, itens 144 a 148', 'medio', true),
(877, 'o_que_e_espiritismo', 'No Capítulo III (itens 146 a 148), por que a justiça divina exige que a falta cometida em uma existência seja reparada por uma expiação equivalente?', 'Porque Deus sente prazer em vingar-se das criaturas que erraram.', 'Porque cada Espírito é solidário com o seu próprio passado, e a expiação ensina pela experiência da dor aquilo que ele fez outros sofrerem.', 'Porque os Espíritos Superiores cobram tributos proporcionais a cada erro.', 'Porque o arrependimento sincero não tem nenhum valor perante as leis morais.', 'Porque somente o sofrimento físico cria a inteligência no Espírito.', 'B', 'Quem abusou da riqueza, do poder ou da saúde aprende, passando pelas provas contrárias, a corrigir o orgulho e a desenvolver a humildade e a caridade.', 'O Que é o Espiritismo - Cap. III, itens 146 a 148', 'medio', true),
(878, 'o_que_e_espiritismo', 'Segundo o Capítulo III (''Esquecimento do passado'', itens 149 a 152), por que Deus concedeu ao homem encarnado o esquecimento temporário de suas existências anteriores?', 'Para impedir que a humanidade progrida nas ciências e nas artes.', 'Porque o cérebro material não possui espaço físico para guardar lembranças.', 'Porque a lembrança precisa das faltas e inimizades passadas humilharia o homem, perturbaria as relações sociais e entravaria o seu livre-arbítrio.', 'Porque o perispírito apaga definitivamente toda a história do Espírito.', 'Para que ninguém possa jamais acreditar na pluralidade das existências.', 'C', 'O esquecimento temporário durante a vida corpórea é um benefício da sabedoria divina: evita vergonhas paralisantes e ódios perpétuos, permitindo que antigos adversários se reconciliem na mesma família.', 'O Que é o Espiritismo - Cap. III, itens 149 a 152', 'facil', true),
(879, 'o_que_e_espiritismo', 'De acordo com o Capítulo III (itens 151 e 152), embora não tenhamos a lembrança detalhada dos fatos de vidas passadas, o que nos resta delas durante a existência atual?', 'Apenas marcas físicas de nascença na pele.', 'O conhecimento exato do idioma que falamos na encarnação anterior.', 'A memória completa dos nomes e datas de todas as nossas famílias passadas.', 'As tendências instintivas, as aptidões inatas e a voz da consciência, que nos adverte contra os erros já sofridos.', 'Absolutamente nada, nem mesmo no campo intelectual ou moral.', 'D', 'Esquecemos os fatos particulares, mas conservamos o resultado da experiência adquirida sob a forma de ideias inatas, aptidões precoces e intuições morais.', 'O Que é o Espiritismo - Cap. III, itens 151 e 152', 'medio', true),
(880, 'o_que_e_espiritismo', 'Segundo o Capítulo III (itens 153 e 154), como a Doutrina Espírita explica as simpatias e antipatias espontâneas entre pessoas que parecem ver-se pela primeira vez?', 'Pela coincidência da cor dos olhos e do timbre da voz.', 'Pela ação exclusiva da temperatura ambiente no sistema nervoso.', 'Por um sorteio aleatório realizado antes do nascimento.', 'Pela diferença de nacionalidade e de classe financeira.', 'Pela intuição vaga de relações anteriores de afeição ou de animosidade que os Espíritos tiveram em existências passadas ou na erraticidade.', 'E', 'Dois Espíritos que se conheceram — como amigos dedicados ou como inimigos — pressentem-se ao se reencontrarem na carne, gerando simpatia imediata ou repulsão instintiva que o dever moral manda vencer.', 'O Que é o Espiritismo - Cap. III, itens 153 e 154', 'medio', true),
(881, 'o_que_e_espiritismo', 'No Capítulo III (''Suicídio'', itens 155 a 157), qual é o ensinamento constante de todos os Espíritos sobre o suicídio?', 'O homem nunca tem o direito de dispor da própria vida; o suicídio é sempre uma transgressão da lei de Deus que agrava os sofrimentos do Espírito.', 'O suicídio é permitido quando a pessoa sofre de doença física incurável.', 'O suicida alcança imediatamente o repouso e o esquecimento de suas dores.', 'O suicídio apressa a evolução espiritual quando motivado por desgosto amoroso.', 'A alma do suicida desintegra-se no instante em que o coração para de bater.', 'A', 'Nos itens 155 a 157, Kardec registra que o suicida procura fugir de um sofrimento passageiro e cai em torturas morais e perispirituais muito mais longas e terríveis.', 'O Que é o Espiritismo - Cap. III, itens 155 a 157', 'facil', true),
(882, 'o_que_e_espiritismo', 'Segundo o Capítulo III (item 156), por que o suicida sente por longo tempo após a morte todas as angústias e impressões da agonia física?', 'Porque o corpo material continua respirando dentro do túmulo.', 'Porque na morte violenta provocada antes do termo natural os laços entre o perispírito e o corpo estavam cheios de vitalidade e só se rompem lentamente.', 'Porque os bons Espíritos recusam-se a ouvir qualquer prece em favor dele.', 'Porque ele perde para sempre a capacidade de arrepender-se.', 'Porque o fluido cósmico congela-se ao redor do local do sepultamento.', 'B', 'Na morte natural a vida orgânica extingue-se pouco a pouco e o desprendimento é suave; no suicídio os laços vitais são quebrados à força em plena vitalidade, repercutindo dolorosamente no perispírito.', 'O Que é o Espiritismo - Cap. III, item 156', 'medio', true),
(883, 'o_que_e_espiritismo', 'De acordo com o Capítulo III (''Loucura, idiotia'', itens 158 a 162), o Espírito do louco ou do idiota de nascença é uma alma inferior ou privada de inteligência?', 'Sim, é uma alma criada sem o princípio da razão humana.', 'Sim, trata-se do espírito de um animal encarnado por engano em corpo humano.', 'Não; o Espírito em si pode ser inteligente, mas acha-se impedido de manifestar seu pensamento pela imperfeição ou lesão dos órgãos cerebrais que lhe servem de instrumento.', 'Não possui alma própria, vivendo apenas pela vida vegetativa do corpo.', 'Perdeu definitivamente a memória e a consciência por toda a eternidade.', 'C', 'O cérebro é o instrumento de manifestação do pensamento na vida corpórea: assim como o mais hábil músico não pode tirar sons harmoniosos de um instrumento quebrado, o Espírito fica tolhido por órgãos imperfeitos.', 'O Que é o Espiritismo - Cap. III, itens 158 a 162', 'medio', true),
(884, 'o_que_e_espiritismo', 'Segundo o Capítulo III (itens 160 a 162), com que finalidade moral e educativa um Espírito inteligente pode ser submetido à dura prova da idiotia ou da loucura?', 'Por mero acidente biológico sem qualquer relação com a justiça de Deus.', 'Para premiar os Espíritos que já atingiram a santidade suprema.', 'Para demonstrar que a matéria governa soberanamente o destino da alma.', 'Como expiação do abuso que fez de sua inteligência, de seu orgulho ou de suas paixões em existência anterior, sofrendo o constrangimento de não poder exprimir-se.', 'Para isentar a família de qualquer dever de caridade e assistência.', 'D', 'No corpo do idiota o Espírito tem consciência interior de sua situação e sofre o constrangimento de não poder comunicar-se, expiando assim o abuso anterior de suas faculdades intelectuais.', 'O Que é o Espiritismo - Cap. III, itens 160 a 162', 'dificil', true),
(885, 'o_que_e_espiritismo', 'Na Biografia de Allan Kardec por Henri Sausse, qual memória premiada em 1831 pela Academia Real de Ciências de Arras o jovem professor Rivail escreveu?', 'Um tratado sobre a aplicação da eletricidade aos telégrafos marítimos.', 'Um estudo astronômico sobre as órbitas dos cometas periódicos.', 'Uma tese médica sobre o tratamento da febre amarela nas colônias.', 'Um romance histórico sobre os druidas da antiga Gália.', '''Qual o sistema de estudos mais em harmonia com as necessidades da época?''.', 'E', 'Henri Sausse destaca que em 1831 a Academia Real de Ciências de Arras premiou a notável memória pedagógica de Rivail sobre a reforma do ensino público na França.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'medio', true),
(886, 'o_que_e_espiritismo', 'Segundo Henri Sausse, que resposta memorável deu o professor Rivail em 1854 quando o Sr. Fortier lhe disse que as mesas falavam ao serem interrogadas?', '''Só acreditarei quando o vir e quando me provarem que uma mesa tem cérebro para pensar, nervos para sentir e que possa tornar-se sonâmbula; até lá, permita que eu não veja nisso mais que um conto para fazer dormir em pé.''', '''Aceito imediatamente o prodígio, pois tudo no universo é sobrenatural e miraculoso.''', '''Jamais assistirei a uma sessão, porque a ciência oficial já proibiu tais estudos.''', '''As mesas falam porque são habitadas pelos gênios elementais da floresta.''', '''Publicarei amanhã mesmo um livro confirmando essas revelações sem precisar verificá-las.''', 'A', 'Essa resposta célebre mostra a prudência e o rigor científico de Rivail: ele não negou a possibilidade de uma força desconhecida, mas exigiu observação direta e explicação racional antes de admitir uma causa inteligente.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'dificil', true),
(887, 'o_que_e_espiritismo', 'Conforme relata Henri Sausse na Biografia, qual era o nome do Espírito protetor de Allan Kardec, que se comunicou com ele pela médium Srta. Aline C. em 1856 confirmando sua missão?', 'O Espírito de São Luís.', 'O Espírito da Verdade (e também o seu Espírito familiar Zéfiro nas reuniões da família Baudin).', 'O Espírito de Emanuel Swedenborg.', 'O Espírito de Galileu Galilei.', 'O Espírito de Joana d''Arc.', 'B', 'Nas sessões da família Baudin manifestava-se o Espírito protetor Zéfiro (que lhe revelou o nome Allan Kardec), e em 1856 o Espírito da Verdade confirmou-lhe a árdua missão de codificar a Doutrina.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'medio', true),
(888, 'o_que_e_espiritismo', 'Segundo a Biografia escrita por Henri Sausse, em que cidade espanhola ocorreu em 9 de outubro de 1861 o célebre auto de fé em que foram queimados trezentos volumes espíritas?', 'Em Madri.', 'Em Sevilha.', 'Em Barcelona.', 'Em Valência.', 'Em Salamanca.', 'C', 'Em 9 de outubro de 1861, por ordem do bispo de Barcelona, foram queimados em praça pública trezentos volumes e brochuras espíritas, fato que repercutiu imensamente a favor da divulgação do Espiritismo.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'dificil', true),
(889, 'o_que_e_espiritismo', 'No Segundo Diálogo (''O Cético''), como o espírita explica por que a Ciência oficial não é competente para julgar a priori a questão dos Espíritos?', 'Porque todos os cientistas são inimigos declarados do progresso humano.', 'Porque a matemática e a física são ciências falsas e ilusórias.', 'Porque o Espiritismo proíbe que médicos e físicos estudem suas obras.', 'Porque as ciências exatas tratam apenas das leis da matéria bruta, enquanto o Espiritismo estuda o elemento espiritual e suas relações com a matéria, o que escapa aos instrumentos de laboratório.', 'Porque os Espíritos apagam a memória dos cientistas que entram nas reuniões.', 'D', 'Cada ciência tem a sua especialidade: a química e a física estudam a matéria inerte; querer submeter o Espírito livre ao cadinho ou ao bisturi é sair do objeto próprio das ciências materiais.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'medio', true),
(890, 'o_que_e_espiritismo', 'No Segundo Diálogo, quando o Cético pergunta se o médium sente o pensamento do Espírito antes de escrever, o que Kardec esclarece?', 'Nunca; o médium fica sempre inconsciente como uma estátua de pedra.', 'Sempre; não existe nenhum médium que escreva sem saber antes toda a frase.', 'Apenas quando o Espírito comunicante é um parente próximo desencarnado.', 'Somente nas noites de tempestade elétrica.', 'Isso depende do tipo de mediunidade: no médium mecânico a mão escreve sem que ele tenha consciência; no médium intuitivo ou semimecânico o pensamento atravessa o seu cérebro no ato da escrita.', 'E', 'Kardec explica ao Cético a distinção entre o médium puramente passivo ou mecânico e o médium intuitivo ou semimecânico, mostrando como em ambos os casos se comprova a independência da ideia comunicada.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'medio', true),
(891, 'o_que_e_espiritismo', 'No Segundo Diálogo (''O Cético''), como Allan Kardec explica o fenômeno das aparições visíveis e até tangíveis (agêneres) de Espíritos?', 'Pela condensação momentânea do fluido perispiritual combinada ao fluido emitido por um médium de efeitos físicos, tornando o perispírito visível e por vezes palpável.', 'Pela ressurreição definitiva da carne e dos ossos que estavam no cemitério.', 'Por simples ilusão de óptica causada por espelhos côncavos nas salas.', 'Pela transformação química do oxigênio do ar em tecido muscular permanente.', 'Pelo desdobramento exclusivo dos animais domésticos presentes na casa.', 'A', 'Em estado normal o perispírito é invisível para os nossos olhos materiais, mas por uma modificação molecular e combinação com o fluido de certos médiuns pode condensar-se até tornar-se visível e momentaneamente tangível.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'dificil', true),
(892, 'o_que_e_espiritismo', 'No Segundo Diálogo, por que Allan Kardec afirma que no Espiritismo não há nada de sobrenatural nem de maravilhoso?', 'Porque o Espiritismo nega a existência de Deus e da alma imortal.', 'Porque todos os fenômenos espíritas repousam sobre leis da Natureza até então desconhecidas; uma vez conhecida a lei que os rege, o maravilhoso desaparece.', 'Porque todas as manifestações mediúnicas são meros truques de prestidigitação.', 'Porque os Espíritos são feitos de matéria sólida idêntica ao ferro.', 'Porque a Ciência já conhecia o perispírito desde a antiguidade clássica.', 'B', 'Deus não derroga as próprias leis que estabeleceu; o que parecia sobrenatural ou miraculoso na ignorância das leis fluídicas e espirituais entra na ordem dos fenômenos naturais explicados pelo Espiritismo.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'facil', true),
(893, 'o_que_e_espiritismo', 'No Terceiro Diálogo (''O Padre''), como o espírita responde à pergunta sobre se o Espiritismo é uma nova religião?', 'Afirmando que o Espiritismo tem bispos, dogmas fechados e sacramentos próprios.', 'Dizendo que o Espiritismo proíbe seus adeptos de entrarem em qualquer igreja.', 'Explicando que o Espiritismo é uma ciência de observação e uma doutrina filosófica de consequências morais que não possui culto material, sacerdócio nem templos, proclamando a liberdade de consciência.', 'Declarando que o Espiritismo exige o batismo obrigatório nas águas do rio Sena.', 'Sustentando que a moral espírita é oposta ao ensino de Jesus Cristo.', 'C', 'Em O Que é o Espiritismo, Kardec esclarece ao Padre que o Espiritismo não se constitui como igreja com sacerdócio ou rituais exteriores, mas acolhe homens de todas as crenças na vivência da caridade cristã.', 'O Que é o Espiritismo - Cap. I, Terceiro Diálogo: O Padre', 'dificil', true),
(894, 'o_que_e_espiritismo', 'Segundo o Capítulo II (itens 31 a 34), todos os Espíritos que são evocados podem atender imediatamente ao chamado?', 'Sim, qualquer Espírito é obrigado a comparecer no instante em que seu nome é pronunciado.', 'Não, porque nenhum Espírito pode jamais ouvir o pensamento dos encarnados.', 'Sim, desde que o evocador pronuncie o nome do Espírito três vezes em voz alta.', 'Não; o Espírito pode estar reencarnado ou ocupado em missão distante, ou a permissão pode ser-lhe negada; nesse caso, ou avisa que não pode vir, ou um Espírito amigo responde por ele.', 'Apenas os Espíritos sofredores têm permissão de atender às evocações.', 'D', 'Kardec explica nos itens 32 a 34 que diversas causas podem impedir a comunicação imediata de um Espírito evocado, inclusive o fato de achar-se reencarnado na Terra ou em outro mundo.', 'O Que é o Espiritismo - Cap. II, itens 31 a 34', 'medio', true),
(895, 'o_que_e_espiritismo', 'No Capítulo II (itens 50 a 54), o que recomenda Allan Kardec àquele que deseja verificar experimentalmente se possui a faculdade de médium escrevente (psicógrafo)?', 'Submeter-se antes a um jejum rigoroso de sete dias no escuro.', 'Comprar aparelhos magnéticos de cobre e cristal.', 'Ingerir substâncias narcóticas para provocar o transe.', 'Exigir que os Espíritos movam os móveis da sala como sinal prévio.', 'Recolher-se em silêncio com fé, elevar o pensamento em prece ao seu Espírito protetor e aguardar com paciência e perseverança, renovando a tentativa por vários dias sem desanimar.', 'E', 'Nos itens 50 a 54, Kardec ensina que o meio de tentar é simples: recolhimento, prece sincera ao anjo guardião e aos bons Espíritos, evitando perguntas frívolas ou interesseiras e perseverando com calma.', 'O Que é o Espiritismo - Cap. II, itens 50 a 54', 'medio', true),
(896, 'o_que_e_espiritismo', 'Segundo o Capítulo II (itens 57 a 62), quais são os sinais característicos pelos quais se reconhece a obsessão e a fascinação mediúnica?', 'A exigência do Espírito de que o médium se isole, rejeite todo exame crítico alheio, escreva incessantemente coisas pueris ou absurdas e acredite cegamente em sua própria infalibilidade.', 'O conselho constante para estudar, praticar a caridade e submeter os escritos ao crivo da razão.', 'A raridade das comunicações e a brevidade das respostas morais.', 'A recomendação de respeitar os deveres familiares e profissionais.', 'O estímulo à humildade, à paciência e ao perdão das ofensas.', 'A', 'Todo Espírito que receia o exame e a discussão, que isola o médium dos conselhos prudentes, que impõe ordens ridículas ou lisonjeia o orgulho é infalivelmente um Espírito mistificador e obsessor.', 'O Que é o Espiritismo - Cap. II, itens 57 a 62', 'dificil', true),
(897, 'o_que_e_espiritismo', 'De acordo com o Capítulo III (itens 108 e 109), a alma existe antes da formação do corpo físico que vai animar?', 'Não; a alma é criada no exato instante em que o recém-nascido respira.', 'Sim; a alma preexiste à união com o corpo, pois é um Espírito que já viveu na erraticidade e em existências anteriores.', 'Apenas as almas dos profetas preexistiam ao nascimento.', 'Não, porque a alma é uma secreção produzida pelo cérebro infantil.', 'Somente nos planetas superiores a alma existe antes do corpo.', 'B', 'No item 109, Kardec afirma categoricamente a preexistência da alma: antes de unir-se ao corpo, ela é um dos Espíritos que povoam o mundo invisível e que se encarna para progredir.', 'O Que é o Espiritismo - Cap. III, itens 108 e 109', 'medio', true),
(898, 'o_que_e_espiritismo', 'Segundo o Capítulo III (itens 122 e 125), como se dá a separação entre a alma e o corpo no momento da morte?', 'De forma sempre instantânea e acompanhada de dores físicas lancinantes para todos os homens.', 'Somente após a decomposição total dos ossos no sepulcro.', 'Gradualmente, desatando-se os laços fluídicos do perispírito sem dor maior do que na vida; para o justo, a separação é pronta e suave como o despertar de um sono.', 'Mediante o rompimento mecânico da coluna vertebral.', 'Apenas quando o sol se põe no horizonte local.', 'C', 'No item 122, Kardec explica que a separação não é brusca nem dolorosa em si mesma: o corpo frequentemente sofre mais durante a vida e a moléstia do que no momento do desprendimento final.', 'O Que é o Espiritismo - Cap. III, itens 122 e 125', 'medio', true),
(899, 'o_que_e_espiritismo', 'Conforme o Capítulo III (itens 131 e 132), o que fazem os Espíritos durante o estado de erraticidade?', 'Dormem em letargia profunda até o momento de reencarnar.', 'Ficam presos imóvelmente ao redor do próprio túmulo.', 'Perdem o livre-arbítrio e tornam-se autômatos inconscientes.', 'Refletem sobre a existência passada, instruem-se, procuram meios de se adiantar e escolhem novas provas para as futuras encarnações.', 'Dedicam-se exclusivamente a produzir ruídos materiais nas casas.', 'D', 'Na erraticidade, o Espírito esclarecido estuda o seu passado, reconhece seus erros, frequenta centros de instrução espiritual e prepara as provas que lhe permitirão avançar em nova existência.', 'O Que é o Espiritismo - Cap. III, itens 131 e 132', 'facil', true),
(900, 'o_que_e_espiritismo', 'Na conclusão de ''O Que é o Espiritismo'', qual é a síntese prática de toda a moral ensinada pelos Espíritos Superiores?', 'O isolamento absoluto do mundo social e a renúncia ao trabalho.', 'A busca do poder terreno e da supremacia intelectual sobre os semelhantes.', 'A observância exclusiva de cerimônias exteriores sem reforma íntima.', 'O fatalismo resignado que dispensa o esforço de aperfeiçoamento.', 'O amor a Deus acima de tudo e a caridade para com o próximo — benevolência para com todos, indulgência para as imperfeições alheias e perdão das ofensas.', 'E', 'Toda a filosofia moral de O Que é o Espiritismo converge para a máxima evangélica da caridade ativa, da fraternidade e da reforma íntima como condição indispensável da felicidade futura.', 'O Que é o Espiritismo - Cap. II, itens 98 a 104 / Cap. III', 'facil', true)
